package contract_test

// Plan 269 利群主机接管 / 利群流量 on SQLite and PostgreSQL: the 4 real entry
// hosts' reports (secret-free fixtures captured 11-17, generated by the agent's
// own reader) are learned into the panel after the step-1 import, and the
// panel's content must equal every host (semantic diff 0) — 火山上海 stable
// front + logswitch v9.1 record-only, 540 warm only on 百度云广州, 279/281 no
// warm / no return_check, phone ports. Then: a line change reaches every host
// that does not pin the value, drift shows as ⚠, traffic counters bill the
// rule + user + per-server quota once (also with a panel landing node), and a
// user over the limit gets the rule's port blocked until the reset.

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"go-backend/internal/store/model"
)

var lkHostFixtures = map[int64]string{58: "baidu", 52: "volc-gz", 60: "aliyun-gz", 61: "volc-sh"}

func lkFixtureReport(t *testing.T, host string, mutate func(map[string]interface{})) json.RawMessage {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "leikwan-host", host+".json"))
	if err != nil {
		t.Fatal(err)
	}
	var m map[string]interface{}
	if err := json.Unmarshal(raw, &m); err != nil {
		t.Fatal(err)
	}
	m["at"] = time.Now().UnixMilli()
	if mutate != nil {
		mutate(m)
	}
	out, _ := json.Marshal(m)
	return out
}

func (e *lkLineEnv) hostView(node int64) map[string]interface{} {
	e.t.Helper()
	list := e.ok("/api/v1/leikwan/host/list", e.admin, map[string]interface{}{})
	for _, it := range list["hosts"].([]interface{}) {
		m := it.(map[string]interface{})
		if num(m["node"].(map[string]interface{})["id"]) == node {
			return m
		}
	}
	e.t.Fatalf("host %d not listed", node)
	return nil
}

func lkDiffLines(mv map[string]interface{}, file string) []string {
	out := []string{}
	diffs, _ := mv["diff"].([]interface{})
	for _, d := range diffs {
		m := d.(map[string]interface{})
		if m["file"] == file {
			for _, l := range m["lines"].([]interface{}) {
				out = append(out, l.(string))
			}
		}
	}
	return out
}

func TestLeiKwanHostTakeoverContract(t *testing.T) {
	for _, dialect := range []string{"sqlite", "postgres"} {
		t.Run(dialect, func(t *testing.T) { leiKwanHostTakeoverFlow(t, dialect) })
	}
}

func leiKwanHostTakeoverFlow(t *testing.T, dialect string) {
	e := newLKLineEnv(t, dialect)
	e.ok("/api/v1/leikwan/import/apply", e.admin, map[string]interface{}{"confirmed": true})
	// Users get 403 on the new admin endpoints.
	for _, p := range []string{"host/learn", "host/manage", "host/force", "host/traffic", "host/sync", "host/unlearn", "rule/prepare-landing"} {
		if out, _ := e.call("/api/v1/leikwan/"+p, e.user, map[string]interface{}{"nodeId": 58}); out.Code != 403 {
			t.Fatalf("%s user access: %+v", p, out)
		}
	}
	// No report yet: learning is refused, 接管 cannot be switched on.
	if out, _ := e.call("/api/v1/leikwan/host/learn", e.admin, map[string]interface{}{"nodeId": 58}); out.Code == 0 {
		t.Fatal("learn without a report accepted")
	}
	if out, _ := e.call("/api/v1/leikwan/host/manage", e.admin, map[string]interface{}{"nodeId": 58, "manage": true}); out.Code == 0 {
		t.Fatal("接管 without a learned profile accepted")
	}
	for node, host := range lkHostFixtures {
		e.h.IngestLeiKwanHostReport(node, lkFixtureReport(t, host, nil))
	}
	// The agent report replaces the step-1 snapshot (source agent).
	if v := e.hostView(61); v["source"] != "agent" || v["snapshot"].(map[string]interface{})["frontChannel"] != "stable" {
		t.Fatalf("SH snapshot: %v %v", v["source"], v["snapshot"])
	}
	for node, host := range lkHostFixtures {
		done := e.ok("/api/v1/leikwan/host/learn", e.admin, map[string]interface{}{"nodeId": node})
		for _, d := range done["learnedDiff"].([]interface{}) {
			if m := d.(map[string]interface{}); m["same"] != true {
				t.Fatalf("%s learn diff not 0: %v", host, m)
			}
		}
		mv := e.hostView(node)["manage"].(map[string]interface{})
		if mv["learned"] != true || num(mv["diffCount"]) != 0 {
			t.Fatalf("%s after learn: %v", host, mv)
		}
	}
	// What the profiles hold (today's per-host behaviour).
	baidu := e.hostView(58)["manage"].(map[string]interface{})
	ov := baidu["overrides"].(map[string]interface{})
	if o540 := ov["540"].(map[string]interface{}); num(o540["warmMain"]) != 10 || o540["warmBackup"] != nil {
		t.Fatalf("baidu 540 override: %v", ov)
	}
	gz := e.hostView(52)["manage"].(map[string]interface{})
	if o540 := gz["overrides"].(map[string]interface{})["540"].(map[string]interface{}); o540["logswitch"] != false || o540["ssFilter"] != "off" {
		t.Fatalf("gz 540 override: %v", gz["overrides"])
	}
	sh := e.hostView(61)["manage"].(map[string]interface{})
	prof := sh["profile"].(map[string]interface{})
	files := prof["files"].(map[string]interface{})
	if files["warm"] == true || files["ssfilter"] == true || files["triggers"] == true || files["logswitch"] != true || len(prof["recordOnly"].([]interface{})) != 9 {
		t.Fatalf("SH profile: %v", prof)
	}
	if ph := baidu["profile"].(map[string]interface{})["phone"].(map[string]interface{}); len(ph) != 6 || num(ph["19263"].(map[string]interface{})["forwardId"]) != 148 {
		t.Fatalf("baidu phone refs: %v", ph)
	}
	// 接管 on (agent offline in the test: saved, sync warning).
	before := num(baidu["rev"])
	on := e.ok("/api/v1/leikwan/host/manage", e.admin, map[string]interface{}{"nodeId": 58, "manage": true})
	if on["manage"] != true || num(on["rev"]) <= before {
		t.Fatalf("manage on: %v", on)
	}
	// A line change reaches every host that does not pin the value: 广港 warm
	// 10 → 8 changes 263 on 百度云广州 / 火山广州 / 阿里广州, not 540 (pinned on
	// 百度云广州), nothing on 火山上海 (no warm file).
	lines := e.ok("/api/v1/leikwan/line/list", e.admin, map[string]interface{}{})
	var gg map[string]interface{}
	for _, l := range lines["lines"].([]interface{}) {
		if m := l.(map[string]interface{}); m["name"] == "利群·广港" {
			gg = m
		}
	}
	accel := gg["accel"].(map[string]interface{})
	accel["warm"].(map[string]interface{})["main"] = 8
	e.ok("/api/v1/leikwan/line/save", e.admin, map[string]interface{}{"id": gg["id"], "name": gg["name"], "routeId": gg["routeId"], "transport": gg["transport"], "backupTunnelId": gg["backupTunnelId"], "accel": accel})
	got := lkDiffLines(e.hostView(58)["manage"].(map[string]interface{}), "warm")
	if strings.Join(got, "|") != "- 263=10|+ 263=8" {
		t.Fatalf("baidu warm diff after line change: %v", got)
	}
	if got := lkDiffLines(e.hostView(60)["manage"].(map[string]interface{}), "warm"); strings.Join(got, "|") != "- 263=10|+ 263=8" {
		t.Fatalf("aliyun warm diff: %v", got)
	}
	if mv := e.hostView(61)["manage"].(map[string]interface{}); num(mv["diffCount"]) != 0 {
		t.Fatalf("SH changed by a warm edit: %v", mv["diff"])
	}
	// Drift / write errors reported by the agent → ⚠ attention.
	e.h.IngestLeiKwanHostReport(58, lkFixtureReport(t, "baidu", func(m map[string]interface{}) {
		m["manage"] = map[string]interface{}{"manage": true, "rev": 3, "drift": []string{"warm"}}
	}))
	list := e.ok("/api/v1/leikwan/host/list", e.admin, map[string]interface{}{})
	if num(list["attention"]) != 1 {
		t.Fatalf("attention count: %v", list["attention"])
	}
	if att := e.hostView(58)["manage"].(map[string]interface{})["attention"].([]interface{}); len(att) != 1 || !strings.Contains(att[0].(string), "漂移") {
		t.Fatalf("drift attention: %v", att)
	}
	// 按面板覆盖 bumps force; only with 接管 on.
	if out, _ := e.call("/api/v1/leikwan/host/force", e.admin, map[string]interface{}{"nodeId": 52}); out.Code == 0 {
		t.Fatal("force on an unmanaged host accepted")
	}
	if f := e.ok("/api/v1/leikwan/host/force", e.admin, map[string]interface{}{"nodeId": 58}); num(f["force"]) != 1 {
		t.Fatalf("force: %v", f)
	}
	// A report carrying something key-like is dropped.
	e.h.IngestLeiKwanHostReport(60, lkFixtureReport(t, "aliyun-gz", func(m map[string]interface{}) {
		m["state"].(map[string]interface{})["frontBuild"] = "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA1"
	}))
	if v := e.hostView(60); v["snapshot"].(map[string]interface{})["frontBuild"] == "AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA1" {
		t.Fatal("secret-like report stored")
	}

	// --- 利群流量 ---
	traffic := func(node int64, host, epoch string, ports map[string][2]int64) {
		e.h.IngestLeiKwanHostReport(node, lkFixtureReport(t, host, func(m map[string]interface{}) {
			m["traffic"] = map[string]interface{}{"epoch": epoch, "ports": ports}
		}))
	}
	rule := func(fid int64) model.LeiKwanRule {
		var x model.LeiKwanRule
		e.must(e.r.DB().Where("forward_id = ?", fid).First(&x).Error)
		return x
	}
	user := func(id int64) model.User {
		var u model.User
		e.must(e.r.DB().First(&u, id).Error)
		return u
	}
	quota := func(uid, node int64) int64 {
		var q model.UserServerQuota
		if err := e.r.DB().Where("user_id = ? AND server_kind = ? AND server_ref_id = ?", uid, "node", node).First(&q).Error; err != nil {
			return -1
		}
		return q.UsedIn + q.UsedOut
	}
	u0 := user(1)
	traffic(58, "baidu", "ep1", map[string][2]int64{"10018": {1000, 5000}, "10044": {7, 7}})
	if x := rule(263); x.InFlow != 1000 || x.OutFlow != 5000 {
		t.Fatalf("263 after first report: %d/%d", x.InFlow, x.OutFlow)
	}
	if u := user(1); u.InFlow-u0.InFlow != 1000 || u.OutFlow-u0.OutFlow != 5000 {
		t.Fatalf("admin user totals: %+v vs %+v", u, u0)
	}
	if q := quota(1, 58); q != 6000 {
		t.Fatalf("per-server quota 百度云广州: %d", q)
	}
	traffic(58, "baidu", "ep1", map[string][2]int64{"10018": {1500, 6000}})
	traffic(58, "baidu", "ep1", map[string][2]int64{"10018": {1500, 6000}}) // same again: nothing
	traffic(52, "volc-gz", "gz1", map[string][2]int64{"10018": {10, 20}})   // another entry host
	if x := rule(263); x.InFlow != 1510 || x.OutFlow != 6020 {
		t.Fatalf("263 after growth: %d/%d", x.InFlow, x.OutFlow)
	}
	if quota(1, 52) != 30 || quota(1, 58) != 7500 {
		t.Fatalf("quotas 火山广州 %d 百度云广州 %d", quota(1, 52), quota(1, 58))
	}
	traffic(58, "baidu", "ep2", map[string][2]int64{"10018": {100, 200}}) // table re-created
	if x := rule(263); x.InFlow != 1610 || x.OutFlow != 6220 {
		t.Fatalf("263 after new epoch: %d/%d", x.InFlow, x.OutFlow)
	}
	// 双向 ×2 on the line doubles the billed bytes.
	e.must(e.r.DB().Model(&model.LeiKwanLine{}).Where("name = ?", "利群·沪日").Update("flow_mode", 2).Error)
	traffic(58, "baidu", "ep2", map[string][2]int64{"10018": {100, 200}, "10015": {10, 10}})
	if x := rule(264); x.InFlow != 20 || x.OutFlow != 20 {
		t.Fatalf("264 双向: %d/%d", x.InFlow, x.OutFlow)
	}

	// Count once: alice's rule lands on her own panel landing node (native
	// server 11): the landing counters bill her total, the entry quota still counts.
	now := time.Now().UnixMilli()
	e.must(e.r.DB().Create(&model.LeiKwanRule{UserID: 2, LineID: 1, AccountID: 1, ForwardID: 9001, Name: "alice 99u", ListenPort: 10099, Transport: "tcp+udp", LandingNodeID: 501, TargetHost: "8.8.8.8", TargetPort: 30001, Status: 1, CreatedTime: now, UpdatedTime: now}).Error)
	a0 := user(2)
	traffic(58, "baidu", "ep2", map[string][2]int64{"10018": {100, 200}, "10015": {10, 10}, "10099": {300, 700}})
	if x := rule(9001); x.InFlow != 300 || x.OutFlow != 700 {
		t.Fatalf("alice rule: %d/%d", x.InFlow, x.OutFlow)
	}
	if a := user(2); a.InFlow != a0.InFlow || a.OutFlow != a0.OutFlow {
		t.Fatalf("alice billed twice: %+v vs %+v", a, a0)
	}
	// The entry machine is billed like a forward path to that landing: the
	// larger of the line bill (1000) and the landing bill (native server
	// default 双向 → 2000), as planLandingForwardBilling does.
	if quota(2, 58) != 2000 {
		t.Fatalf("alice entry quota: %d", quota(2, 58))
	}
	// The rule rows show the traffic.
	rl := e.ok("/api/v1/leikwan-rule/list", e.admin, map[string]interface{}{})
	found := false
	for _, it := range rl["rules"].([]interface{}) {
		m := it.(map[string]interface{})
		if num(m["forwardId"]) == 263 {
			found = num(m["inFlow"]) == 1610 && num(m["outFlow"]) == 6220 && m["blockReason"] == ""
		}
	}
	if !found {
		t.Fatalf("rule list traffic of 263 missing (%d rules)", len(rl["rules"].([]interface{})))
	}

	// Over the limit → blocked; reset → open again.
	e.must(e.r.DB().Model(&model.User{}).Where("id = ?", 2).Updates(map[string]interface{}{"flow": 1, "in_flow": 2 << 30, "out_flow": 0}).Error)
	e.h.ReconcileLeiKwanBlocks()
	if x := rule(9001); x.BlockReason != "总流量已用完" {
		t.Fatalf("block reason: %q", x.BlockReason)
	}
	if x := rule(263); x.BlockReason != "" {
		t.Fatalf("admin rule blocked: %q", x.BlockReason)
	}
	e.must(e.r.DB().Model(&model.User{}).Where("id = ?", 2).Updates(map[string]interface{}{"in_flow": 0}).Error)
	e.h.ReconcileLeiKwanBlocks()
	if x := rule(9001); x.BlockReason != "" {
		t.Fatalf("not unblocked: %q", x.BlockReason)
	}
	e.must(e.r.DB().Model(&model.User{}).Where("id = ?", 2).Update("exp_time", now-1000).Error)
	e.h.ReconcileLeiKwanBlocks()
	if x := rule(9001); x.BlockReason != "账号已到期" {
		t.Fatalf("expiry block: %q", x.BlockReason)
	}
	e.must(e.r.DB().Model(&model.User{}).Where("id = ?", 2).Update("exp_time", now+864e5).Error)
	// Per-server quota of an entry host used up.
	e.must(e.r.DB().Model(&model.UserServerQuota{}).Where("user_id = ? AND server_ref_id = ?", 2, 58).Updates(map[string]interface{}{"limit_bytes": 500, "limit_override": true, "paused": true}).Error)
	e.h.ReconcileLeiKwanBlocks()
	if x := rule(9001); !strings.Contains(x.BlockReason, "百度云广州") {
		t.Fatalf("server quota block: %q", x.BlockReason)
	}

	// 待切换: prepare a panel landing node for 263 (admin's own node only).
	if out, _ := e.call("/api/v1/leikwan/rule/prepare-landing", e.admin, map[string]interface{}{"id": rule(263).ID, "landingNodeId": 501}); out.Code == 0 {
		t.Fatal("prepared someone else's landing node")
	}
	e.must(e.r.DB().Create(&model.LandingNode{ID: 601, UserID: 1, LandingServerID: 11, Name: "263-99u", Protocol: "ss2022", Port: 30010, InboundTag: "lk263", Method: "2022-blake3-aes-128-gcm", ServerKey: "c2VydmVyMTIzNDU2Nzg5MA==", UserKey: "dXNlcjEyMzQ1Njc4OTAxMg==", Status: "active"}).Error)
	e.ok("/api/v1/leikwan/rule/prepare-landing", e.admin, map[string]interface{}{"id": rule(263).ID, "landingNodeId": 601})
	if x := rule(263); x.PendingLandingNodeID != 601 {
		t.Fatalf("pending: %d", x.PendingLandingNodeID)
	}
	// 换落地 is refused while an entry host that filters 263 is not under 接管.
	if out, _ := e.call("/api/v1/leikwan-rule/update", e.admin, map[string]interface{}{"id": rule(263).ID, "changeTarget": true, "landingNodeId": 601}); out.Code == 0 || !strings.Contains(out.Msg, "还没接管") {
		t.Fatalf("filter key guard: %+v", out)
	}
	if x := rule(263); x.TargetPort != 10016 {
		t.Fatalf("target changed despite the guard: %d", x.TargetPort)
	}
}
